const _ = require('lodash');
// Confirm lodash version
console.log("lodash version:", require('lodash/package.json').version);

// Reproduce app's mergePreferences exactly: _.merge({}, current, input)
function mergePreferences(current, input) { return _.merge({}, current, input); }

