// Vector B: constructor.prototype
const b = JSON.parse('{"constructor":{"prototype":{"y":"B"}}}');
mergePreferences({}, b);
console.log("vecB ({}).y =", ({}).y);

// Vector C: array-like
const c = JSON.parse('[{"__proto__":{"z":"C"}}]');
mergePreferences({}, c);
console.log("vecC ({}).z =", ({}).z);

// Also test _.set just in case (not used in app)
_.set({}, '__proto__.w', 'D');
console.log("vecD _.set ({}).w =", ({}).w);
EOF
